import type { MultiSelectProps } from "./multi-select.types";
import type { CSSObject } from "@emotion/react";
import type { ComponentStyleVariantConfig, Theme } from "@types";

import { MenuItemClasses } from "@components/menu";
import { CheckboxClasses } from "@components/checkbox";
import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "MultiSelect";

// Generate child element class names for the component, should match available style slots
export const MultiSelectClasses = {
  root: "exp-textura_multi-select",
  trigger: "exp-textura_multi-select_trigger",
  triggerError: "exp-textura_multi-select_trigger_error",
  triggerContent: "exp-textura_multi-select_trigger_content",
  triggerItems: "exp-textura_multi-select_trigger_items",
  clearIconButton: "exp-textura_multi-select_clear_icon_button",
  content: "exp-textura_multi-select_content",
  item: "exp-textura_multi-select_item",
  items: "exp-textura_multi-select_items",
  icon: "exp-textura_multi-select_icon",
  search: "exp-textura_multi-select_search",
  noResults: "exp-textura_multi-select_no_results",
  chip: "exp-textura_multi-select_chip",
  avatarChip: "exp-textura_multi-select_avatar_chip",
  chipCloseButton: "exp-textura_multi-select_chip_close_button",
};

// Set up style variant settings for the component (if more than "default"), using style slots
const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
  critical: {
    trigger: {
      color: theme.inputDropdown.critical.color.content.enabled,
      border: `${theme.toRem(theme.inputDropdown.border.width)} solid ${theme.inputDropdown.critical.color.border.enabled}`,
    },
    triggerHover: {
      borderColor: theme.inputDropdown.critical.color.border.hover,
      color: theme.inputDropdown.critical.color.content.hover,
    },
    triggerFocus: {
      borderColor: theme.inputDropdown.critical.color.border.pressed,
      color: theme.inputDropdown.critical.color.content.pressed,
    },
    triggerDisabled: {
      borderColor: theme.inputDropdown.critical.color.border.disabled,
      color: theme.inputDropdown.critical.color.content.disabled,
      [`& .${MultiSelectClasses.icon}`]: {
        color: theme.inputDropdown.default.color.content.disabled,
      },
    },
    icon: {
      color: theme.color.content.utility.critical,
    },
    triggerItems: {
      color: theme.inputDropdown.critical.color.content.enabled,
    },
  },
});

const generateStyles = (props: MultiSelectProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<MultiSelectProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    display: "inline-block",
    position: "relative",
    width: "100%",

    [`.${MultiSelectClasses.trigger}`]: {
      display: "flex",
      alignItems: "center",
      justifyContent: "space-between",
      padding: `${theme.toRem(theme.spacing[4])} ${theme.toRem(theme.spacing[8])}`,
      border: `${theme.toRem(theme.inputDropdown.border.width)} solid ${
        theme.inputDropdown.default.color.border.enabled
      }`,
      ...theme.typography.body.md,
      borderRadius: theme.toRem(theme.inputDropdown.border.radius),
      minHeight: theme.toRem(32),
      width: "100%",
      backgroundColor: theme.color.background.default,
      cursor: "pointer",
      "&:hover": {
        borderColor: theme.inputDropdown.default.color.border.hover,
        color: theme.inputDropdown.default.color.content.hover,
        ...styleSlots?.triggerHover,
      },
      "&:focus-visible": {
        outline: "none",
        borderColor: theme.inputDropdown.default.color.border.pressed,
        color: theme.inputDropdown.default.color.content.pressed,
        ...styleSlots?.triggerFocus,
      },
      "&[data-disabled='true']": {
        backgroundColor: theme.color.background.default,
        borderColor: theme.inputDropdown.default.color.border.disabled,
        color: theme.inputDropdown.default.color.content.disabled,
        pointerEvents: "none",
        [`& .${MultiSelectClasses.icon}`]: {
          color: theme.inputDropdown.default.color.content.disabled,
        },
        ...styleSlots?.triggerDisabled,
      },
      ...styleSlots?.trigger,
    },

    [`.${MultiSelectClasses.triggerContent}`]: {
      display: "flex",
      flex: 1,
      alignItems: "flex-start",
      gap: theme.toRem(theme.spacing[4]),
      ...styleSlots?.triggerContent,
    },

    [`.${MultiSelectClasses.triggerItems}`]: {
      display: "flex",
      flex: 1,
      flexWrap: "wrap",
      alignItems: "center",
      gap: theme.toRem(theme.spacing[4]),
      minHeight: theme.toRem(theme.spacing[24]),
      color: theme.inputDropdown.default.color.content.enabled,
      "&[data-disabled='true']": {
        opacity: 0.5,
        ...styleSlots?.triggerItemsDisabled,
      },
      ...styleSlots?.triggerItems,
    },

    [`.${MultiSelectClasses.clearIconButton}`]: {
      position: "relative",
      top: "unset",
      marginInlineEnd: theme.toRem(theme.spacing[8]),
      color: theme.color.content.icon,
      "&:disabled": {
        color: "inherit !important",
        ...styleSlots?.clearIconButtonDisabled,
      },
      ...styleSlots?.clearIconButton,
    },

    [`&.${MultiSelectClasses.content}`]: {
      padding: `${theme.toRem(theme.spacing[8])} 0`,
      borderRadius: theme.toRem(theme.border.radius.sm),
      backgroundColor: theme.color.background.default,
      maxWidth: "unset",
      display: "flex",
      flexDirection: "column",
      overflow: "hidden",
      width: "100%",
      height: "100%",
      minHeight: 0,
      ...styleSlots?.content,
    },

    [`.${MultiSelectClasses.items}`]: {
      margin: theme.toRem(theme.spacing[8]),
      flex: 1,
      overflowY: "auto",
      overscrollBehavior: "contain",
      ...styleSlots?.items,
    },

    [`.${MultiSelectClasses.chip}`]: {
      ...styleSlots?.chip,
    },

    [`.${MultiSelectClasses.avatarChip}`]: {
      ...styleSlots?.avatarChip,
    },

    [`.${MultiSelectClasses.chipCloseButton}`]: {
      ...styleSlots?.chipCloseButton,
    },

    [`.${MultiSelectClasses.item}`]: {
      ...styleSlots?.item,
      // Prevent checkbox hover state when hovering the item, as the item itself handles highlight
      [`.${CheckboxClasses.root}:hover`]: {
        borderColor: theme.inputSelect.checkbox.off.default.color.content.enabled,
      },

      [`.${MenuItemClasses.label}`]: {
        ...styleSlots?.itemLabel,
      },
      [`.${MenuItemClasses.subtext}`]: {
        ...styleSlots?.itemSubtext,
      },
      [`.${MenuItemClasses.leadingIcon}`]: {
        ...styleSlots?.itemLeadingIcon,
      },
      [`.${MenuItemClasses.trailingIcon}`]: {
        ...styleSlots?.itemTrailingIcon,
      },
      [`.${MenuItemClasses.text}`]: {
        ...styleSlots?.itemText,
      },

      "&[data-highlighted]": {
        [`.${MenuItemClasses.subtext}`]: {
          ...styleSlots?.itemSubtextHover,
        },
      },
      "&:active": {
        [`.${MenuItemClasses.subtext}`]: {
          ...styleSlots?.itemSubtextPressed,
        },
      },
      "&[data-state=checked]": {
        [`.${MenuItemClasses.subtext}`]: {
          ...styleSlots?.itemSubtextSelected,
        },
      },
      "&[data-disabled]": {
        [`.${MenuItemClasses.subtext}`]: {
          ...styleSlots?.itemSubtextDisabled,
        },
      },
    },

    [`.${MultiSelectClasses.icon}`]: {
      position: "relative",
      top: theme.toRem(theme.spacing[4]),
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      marginInlineStart: "auto",
      flex: 0,
      width: theme.toRem(16),
      height: theme.toRem(16),
      fontSize: theme.toRem(16),
      color: theme.color.content.icon,
      ...styleSlots?.icon,
    },

    [`.${MultiSelectClasses.search}`]: {
      ...styleSlots?.search,
    },

    [`.${MultiSelectClasses.noResults}.${MenuItemClasses.root}[data-disabled]`]: {
      padding: `${theme.toRem(theme.spacing[4])} ${theme.toRem(theme.spacing[8])}`,
      color: theme.color.content.weak,
      ...styleSlots?.noResults,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledMultiSelect = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<MultiSelectProps>((props) => generateStyles(props));
